from textutil.truncate import truncate


def test_short_text_untouched():
    assert truncate("short", 10) == "short"


def test_word_boundary():
    assert truncate("The quick brown fox jumps", 15) == "The quick..."


def test_within_limit():
    assert len(truncate("alpha beta gamma delta", 12)) <= 12


def test_no_mid_word_cut():
    assert truncate("alpha betagamma delta", 12) == "alpha..."


def test_single_long_word_no_mid_word_cut():
    assert truncate("Supercalifragilistic word", 10) == "..."

